import React from "react";
import tutorsimulaLogo from "../../assets/tutorsimula-logo-purple.png";
import CircularCoverflow from "./CircularCoverflow.jsx";

export default function Hero() {
  const roles = [
    "Frontend Engineer",
    "Backend Engineer",
    "Full-Stack Developer",
    "Algorithms & Data Structures (DSA)",
    "Data Analyst",
    "Machine Learning Engineer",
    "Data Scientist",
    "DevOps Engineer",
    "Cloud Engineer",
  ];

  return (
    <section className="w-full pt-20 md:pt-24 pb-4 md:pb-6 bg-gradient-to-b from-gray-950 via-gray-900 to-gray-950">
      <style>{`
        @keyframes ts-heartbeat {
          0%, 100% { transform: scale(1); }
          10%      { transform: scale(1.08); }
          20%      { transform: scale(1); }
          30%      { transform: scale(1.05); }
          40%      { transform: scale(1); }
        }
        @keyframes ts-floaty {
          0%   { transform: translateY(0); }
          50%  { transform: translateY(-6px); }
          100% { transform: translateY(0); }
        }
      `}</style>

      <div className="text-center">
        <img
          src={tutorsimulaLogo}
          alt="TutorSimula Logo"
          className="w-36 md:w-48 h-auto mx-auto mb-3"
          style={{
            animation:
              "ts-floaty 7s ease-in-out infinite, ts-heartbeat 2.2s ease-in-out infinite",
            transformOrigin: "50% 50%",
            filter: "drop-shadow(0 0 18px rgba(168,85,247,0.35))",
            willChange: "transform",
          }}
          onError={(e) => {
            e.currentTarget.src =
              "data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNk+A8AAQUBAScY42YAAAAASUVORK5CYII=";
          }}
        />

        <h1 className="text-3xl md:text-5xl font-extrabold leading-tight">
          Master Technical Interviews with AI-Powered Practice
        </h1>
        <p className="mt-2 text-lg md:text-xl text-white/90">
          Personalized mock interviews, real-time feedback, and a pro setup.
        </p>
        <p className="mt-1 text-base md:text-lg text-white/80">
          Start your professional journey today.
        </p>
      </div>

      {/* Spinner very close to hero text */}
      <div className="mt-1 md:mt-2">
        <CircularCoverflow
          items={roles}
          radius={260}
          card={{ w: 240, h: 160 }}
          autoplayMs={2500}
          offsetX={0}   // Set to 0 for proper centering
        />
      </div>
    </section>
  );
}