// src/pages/CompanyGuideHub.jsx
import React, { useMemo } from "react";
import { useParams, useLocation, useNavigate } from "react-router-dom";
import NavBar from "../NavBar.jsx";
// import Footer from "../components/Footer.jsx";  // ← removed
import GoogleCompanyGuide from "./CompanyGuide.jsx"; // keep your Google page intact

// helpers (NO hooks here)
const toTitle = (s = "") =>
  s.replace(/[-_]+/g, " ").replace(/\b\w/g, (m) => m.toUpperCase()).trim();

function brandTint(name = "") {
  let h = 0;
  for (let i = 0; i < name.length; i++) h = (h * 31 + name.charCodeAt(i)) % 360;
  return `hsl(${h}, 85%, 60%)`;
}

export default function CompanyGuideHub() {
  // ✅ Hooks ONLY inside component
  const { slug = "" } = useParams();
  const { state } = useLocation();

  const companyFromState = state?.company;
  const tech = state?.tech || null;

  const company = useMemo(() => {
    if (companyFromState) return companyFromState;
    if (slug.includes("alphabet") || slug.includes("google")) return "Google";
    return toTitle(slug);
  }, [slug, companyFromState]);

  const isGoogle = /google/.test(slug) || company === "Google";

  return (
    <div className="min-h-screen bg-[#0f172a] text-white">
      <NavBar />

      

      {/* Keep your Google page exactly as-is; otherwise show a generic guide */}
      {isGoogle ? (
        <GoogleCompanyGuide />
      ) : (
        <GenericCompanyGuide company={company} tech={tech} />
      )}

      {/* <Footer />  ← removed */}
    </div>
  );
}

// ✅ Component (uses hook inside)
function GoToPackageButtons({ company, tech }) {
  const navigate = useNavigate();
  const state = tech ? { company, tech } : { company };

  return (
    <div className="rounded-3xl border border-white/10 bg-white/[0.05] backdrop-blur p-4 flex gap-2">
      <button
        onClick={() => navigate("/select-package", { state })}
        className="px-4 py-2 rounded-full bg-white text-gray-900 font-semibold"
      >
        Straight {company} MockInterview →
      </button>
      
      <button
        onClick={() => navigate(-1)}
        className="px-4 py-2 rounded-full bg-white/10 hover:bg-white/15 border border-white/15"
      >
        Back
      </button>
    </div>
  );
}

// ✅ Component (uses hook inside)
function GenericCompanyGuide({ company, tech }) {
  const navigate = useNavigate();
  const tint = brandTint(company);

  return (
    <div className="relative overflow-hidden">
      <div className="mx-auto max-w-7xl px-4 pt-10 pb-8">
        <div className="rounded-3xl border border-white/10 bg-white/[0.05] backdrop-blur p-6 md:p-10 relative overflow-hidden">
          <div
            className="absolute -top-16 -right-16 h-56 w-56 rounded-full blur-3xl opacity-30"
            style={{ background: `radial-gradient(closest-side, ${tint}, transparent)` }}
          />
          <p className="text-xs md:text-sm text-white/70">TutorSimula Company Guide</p>
          <h1 className="text-3xl md:text-5xl font-extrabold tracking-tight mt-2">
            {company} — Overview{tech ? ` • ${toTitle(tech)} Track` : ""}
          </h1>
          <p className="mt-3 text-white/80 max-w-3xl">
            A common template for {company}. Fill it with company specifics anytime.
          </p>

          <div className="mt-5 flex flex-wrap gap-2">
            <button
              onClick={() =>
                navigate("/select-package", {
                  state: tech ? { company, tech } : { company },
                })
              }
              className="px-4 py-2 rounded-full font-semibold text-gray-900"
              style={{ background: tint }}
            >
              Straight {company} MockInterview →
            </button>
            
            <button
              onClick={() => navigate(-1)}
              className="px-4 py-2 rounded-full bg-white/10 hover:bg-white/15 border border-white/15"
            >
              Back
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}
