// src/components/launch/StickySocialRail.jsx
import React from "react";

/**
 * StickySocialRail
 * ----------------
 * A fixed, right-aligned vertical rail of social icons.
 *
 * Props:
 *  - links?: { facebook, instagram, x, linkedin, youtube }
 *  - hiddenOnMobile?: boolean (default true)
 */
export default function StickySocialRail({
  hiddenOnMobile = true,
  links = {
    facebook: "https://facebook.com/tutorsimula",
    instagram: "https://instagram.com/tutorsimula",
    x: "https://x.com/tutorsimula",
    linkedin: "https://www.linkedin.com/company/tutorsimula",
    youtube: "https://www.youtube.com/@tutorsimula",
  },
}) {
  const wrapPos =
    "fixed right-3 top-1/2 -translate-y-1/2 z-50 flex flex-col items-center gap-3";
  const responsive = hiddenOnMobile ? "hidden md:flex" : "flex";

  const IconButton = ({ href, label, children }) => (
    <a
      href={href}
      target="_blank"
      rel="noopener noreferrer"
      aria-label={label}
      className="ts-social group inline-grid place-items-center size-11 rounded-full
                 bg-white/10 border border-white/15
                 hover:bg-white/20 focus:bg-white/20
                 transition focus:outline-none focus-visible:ring-2 focus-visible:ring-blue-300/70"
      title={label}
    >
      {children}
    </a>
  );

  return (
    <div className={`${wrapPos} ${responsive}`}>
      {/* Facebook */}
      <IconButton href={links.facebook} label="Facebook">
        <svg width="22" height="22" viewBox="0 0 24 24" className="fill-white/90">
          <path d="M22 12.06C22 6.5 17.52 2 12 2S2 6.5 2 12.06c0 5 3.66 9.14 8.44 9.94v-7.03H7.9v-2.9h2.54V9.4c0-2.5 1.5-3.88 3.78-3.88 1.1 0 2.25.2 2.25.2v2.47h-1.27c-1.25 0-1.64.78-1.64 1.58v1.9h2.79l-.45 2.9h-2.34V22c4.78-.8 8.44-4.93 8.44-9.94Z" />
        </svg>
      </IconButton>

      {/* Instagram */}
      <IconButton href={links.instagram} label="Instagram">
        <svg width="22" height="22" viewBox="0 0 24 24" className="fill-white/90">
          <path d="M7 2h10a5 5 0 0 1 5 5v10a5 5 0 0 1-5 5H7a5 5 0 0 1-5-5V7a5 5 0 0 1 5-5Zm0 2a3 3 0 0 0-3 3v10a3 3 0 0 0 3 3h10a3 3 0 0 0 3-3V7a3 3 0 0 0-3-3H7Zm5 3.5A5.5 5.5 0 1 1 6.5 13 5.51 5.51 0 0 1 12 7.5Zm0 2A3.5 3.5 0 1 0 15.5 13 3.5 3.5 0 0 0 12 9.5ZM18 6.2a1 1 0 1 1-1.4 1.43A1 1 0 0 1 18 6.2Z" />
        </svg>
      </IconButton>

      {/* X (Twitter) */}
      <IconButton href={links.x} label="X (formerly Twitter)">
        <svg width="22" height="22" viewBox="0 0 24 24" className="fill-white/90">
          <path d="M3 3h4.7l4.1 5.58L16.8 3H21l-7.2 9.2 6.8 8.8h-4.7l-4.3-5.83L7 21H3l7.3-9.2L3 3Z" />
        </svg>
      </IconButton>

      {/* LinkedIn */}
      <IconButton href={links.linkedin} label="LinkedIn">
        <svg width="22" height="22" viewBox="0 0 24 24" className="fill-white/90">
          <path d="M4.98 3.5a2.25 2.25 0 1 1 0 4.5 2.25 2.25 0 0 1 0-4.5ZM3.5 9h3v12h-3V9Zm6 0h2.86v1.64h.04c.4-.76 1.38-1.56 2.83-1.56C18.5 9.08 20 10.6 20 13.3V21h-3v-6.66c0-1.59-.57-2.67-1.99-2.67-1.08 0-1.72.73-2 1.43-.1.24-.12.58-.12.92V21h-3V9Z" />
        </svg>
      </IconButton>

      {/* YouTube */}
      <IconButton href={links.youtube} label="YouTube">
        <svg width="22" height="22" viewBox="0 0 24 24" className="fill-white/90">
          <path d="M23 12s0-3-.38-4.47a3 3 0 0 0-2.1-2.1C19 5 12 5 12 5s-7 0-8.52.43a3 3 0 0 0-2.1 2.1C1 9 1 12 1 12s0 3 .38 4.47a3 3 0 0 0 2.1 2.1C5 19 12 19 12 19s7 0 8.52-.43a3 3 0 0 0 2.1-2.1C23 15 23 12 23 12ZM10 15.5v-7l6 3.5-6 3.5Z" />
        </svg>
      </IconButton>

      <style>{`
        .ts-social {
          box-shadow: 0 0 0 rgba(147,197,253,0);
          transition: transform .18s ease, box-shadow .25s ease;
        }
        .ts-social:hover,
        .ts-social:focus-visible {
          transform: translateY(-1px);
          box-shadow: 0 8px 22px rgba(147, 197, 253, 0.25);
        }
      `}</style>
    </div>
  );
}
