// src/pages/MockInterviewComponent.jsx
import React, { useMemo } from "react";
import { useLocation, useNavigate } from "react-router-dom";
import NavBar from "../NavBar.jsx";
import Footer from "../components/Footer.jsx";

const LEVEL_META = {
  L1: {
    key: "L1",
    title: "FresherLaunch",
    hue: "rgb(34 197 94)", // emerald
    gradient: "linear-gradient(135deg, rgba(34,197,94,.25), rgba(59,130,246,.15))",
    pill: "bg-emerald-500",
    blurb:
      "Begin here if you’re starting out. Friendly pace, clear prompts, guided structure.",
  },
  L2: {
    key: "L2",
    title: "FresherSkilled",
    hue: "rgb(59 130 246)", // blue
    gradient: "linear-gradient(135deg, rgba(59,130,246,.25), rgba(168,85,247,.15))",
    pill: "bg-blue-500",
    blurb:
      "For candidates with projects/internships. Deeper prompts, tighter timeboxes, richer feedback.",
  },
  L3: {
    key: "L3",
    title: "Experienced",
    hue: "rgb(168 85 247)", // purple
    gradient: "linear-gradient(135deg, rgba(168,85,247,.25), rgba(34,197,94,.15))",
    pill: "bg-purple-500",
    blurb:
      "For working pros. Production realism, systems thinking, and panel-level depth.",
  },
};

// 7 STAGES with level-specific detail/difficulty
const STAGES = [
  {
    id: 1,
    name: "Phone Screening — Talent Connect",
    copy: {
      L1: "5–7 min friendly intro; role basics, availability, expectations.",
      L2: "8–10 min targeted pass; JD alignment, project depth, timeline.",
      L3: "10–12 min hiring-bar triage; scope owned, impact, expectations.",
    },
    chips: { L1: ["Warm-up"], L2: ["Fit"], L3: ["Bar Check"] },
  },
  {
    id: 2,
    name: "Communication Assessment — Resume Analyzer",
    copy: {
      L1: "ATS parse + gaps; STAR basics for 2–3 stories.",
      L2: "Evidence-first stories; numbers, scope, lessons.",
      L3: "Leadership narratives; cross-team influence, trade-offs.",
    },
    chips: { L1: ["STAR"], L2: ["Metrics"], L3: ["Leadership"] },
  },
  {
    id: 3,
    name: "Cognitive Assessment — Initial Check",
    copy: {
      L1: "10 min logic/patterns; easy→medium.",
      L2: "15 min reasoning sets; medium.",
      L3: "20 min problem solving; medium→hard under time.",
    },
    chips: { L1: ["Logic"], L2: ["Reasoning"], L3: ["Pressure"] },
  },
  {
    id: 4,
    name: "Coding Assessment — Challenge",
    copy: {
      L1: "1 easy DSA / simple function + basic tests.",
      L2: "1 medium problem; edge cases & readability.",
      L3: "Prod-style task; tests, perf hints, clarity.",
    },
    chips: { L1: ["Basics"], L2: ["Edge Cases"], L3: ["Prod-Ready"] },
  },
  {
    id: 5,
    name: "Technical Assessment — Perform",
    copy: {
      L1: "Mini API/UI walkthrough; simple trade-offs.",
      L2: "Design mini; data model, rate limit, failure modes.",
      L3: "Architecture depth; scale, reliability, observability.",
    },
    chips: { L1: ["Walkthrough"], L2: ["Design"], L3: ["Architecture"] },
  },
  {
    id: 6,
    name: "Capstone Assessment — Achieve",
    copy: {
      L1: "Ship a small feature with a brief demo.",
      L2: "Build + tests; explain decisions, alternatives.",
      L3: "Build & defend; metrics, rollback, next steps.",
    },
    chips: { L1: ["Build"], L2: ["Build+Tests"], L3: ["Build+Defend"] },
  },
  {
    id: 7,
    name: "Panel Interview — Final Battle",
    copy: {
      L1: "Supportive panel; clarity & collaboration focus.",
      L2: "Balanced panel; scope, ownership, impact.",
      L3: "Senior panel; strategy, risk, leadership signals.",
    },
    chips: { L1: ["Supportive"], L2: ["Ownership"], L3: ["Leadership"] },
  },
];

export default function MockInterviewComponent() {
  const { state } = useLocation();
  const navigate = useNavigate();

  // Defaults if user hit the route directly
  const company = state?.company || "Your Company";
  const level = state?.level || "L1";
  const packageLPA = state?.packageLPA ?? 10;
  const expYears = state?.expYears ?? 0.5;

  const meta = LEVEL_META[level] ?? LEVEL_META.L1;

  const onSubscribe = () => {
    navigate("/subscription", {
      state: { level, company, packageLPA, expYears, plan: meta.title },
    });
  };

  return (
    <div className="min-h-screen bg-gray-800 text-white">
      <NavBar />

      <div className="pt-16 md:pt-20 px-4 md:px-6 max-w-7xl mx-auto">
        {/* Header */}
        <div
          className="rounded-3xl p-6 md:p-10 border border-white/10 backdrop-blur relative overflow-hidden"
          style={{ background: "rgba(255,255,255,0.04)" }}
        >
          <div
            className="absolute -top-24 -right-24 w-96 h-96 rounded-full blur-3xl opacity-30"
            style={{ background: meta.gradient }}
          />
          <p className="text-xs md:text-sm text-white/70">TutorSimula Mock Interview</p>
          <h1 className="text-3xl md:text-5xl font-extrabold tracking-tight mt-2">
            {meta.title}
          </h1>
          <p className="mt-3 text-white/80 max-w-3xl">{meta.blurb}</p>

          {/* Selection summary */}
          <div className="mt-6 grid sm:grid-cols-3 gap-3 text-sm">
            <SummaryCard label="Company" value={company} />
            <SummaryCard label="Package" value={`${Math.round(packageLPA)} LPA`} />
            <SummaryCard label="Experience" value={`${Number(expYears).toFixed(1)} Y`} />
          </div>

          {/* Subscribe */}
          <div className="mt-6 flex flex-wrap gap-3">
            <button
              onClick={() => navigate(-1)}
              className="px-5 py-2.5 rounded-full bg-white/10 hover:bg-white/15 border border-white/15"
            >
              Back
            </button>
            <button
              onClick={onSubscribe}
              className="px-6 py-2.5 rounded-full font-semibold text-gray-900"
              style={{ background: meta.hue }}
            >
              Subscribe to {meta.title} →
            </button>
          </div>
        </div>

        {/* 7-Stage Timeline */}
        <section className="mt-8 md:mt-10">
          <h2 className="text-xl md:text-2xl font-bold mb-3">Your 7 Stages</h2>
          <p className="text-white/70 mb-6">
            Each stage adapts to your level. Expect the same structure with calibrated difficulty.
          </p>

          <ol className="relative border-s border-white/10 pl-6 space-y-6">
            {STAGES.map((s) => (
              <li key={s.id} className="relative">
                <span
                  className="absolute -start-3.5 top-1 size-3 rounded-full shadow"
                  style={{ background: meta.hue }}
                />
                <div className="rounded-2xl border border-white/10 bg-white/[0.04] p-4">
                  <div className="flex flex-wrap items-center gap-2 justify-between">
                    <h3 className="text-base md:text-lg font-semibold">{s.name}</h3>
                    <div className="flex flex-wrap gap-2">
                      {s.chips[level].map((c) => (
                        <span
                          key={c}
                          className="px-2.5 py-1 rounded-full text-[11px] bg-white/10 border border-white/10"
                        >
                          {c}
                        </span>
                      ))}
                    </div>
                  </div>
                  <p className="text-white/75 mt-1">{s.copy[level]}</p>
                </div>
              </li>
            ))}
          </ol>
        </section>

        {/* Footer note */}
        <div className="mt-10 text-xs text-white/60">
          Tip: You can always revisit package/experience to auto-switch level in Select Package.
        </div>
      </div>

      
    </div>
  );
}

function SummaryCard({ label, value }) {
  return (
    <div className="rounded-2xl bg-white/[0.03] border border-white/10 p-4">
      <div className="text-white/70">{label}</div>
      <div className="text-xl font-bold">{value}</div>
    </div>
  );
}
