import React from "react";
import { useNavigate } from "react-router-dom";
import NavBar from "../NavBar.jsx";
import Footer from "../components/Footer.jsx";

export default function SelectInterviewType() {
  const navigate = useNavigate();

  return (
    <div
      className="min-h-screen bg-gray-800 text-white flex flex-col overflow-x-hidden"
      style={{ scrollBehavior: "smooth" }}
    >
      <NavBar />

      <main className="flex-1 w-full py-10 md:py-16">
        <div className="max-w-5xl mx-auto px-4 md:px-6">
          <h1 className="text-2xl md:text-3xl font-bold mb-6">
            Select the mockinterview you want
          </h1>

          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <button
              onClick={() => navigate("/mocks/company-based")}
              className="rounded-2xl border border-emerald-400/60 px-6 py-4 text-left backdrop-blur-md bg-white/5 hover:bg-white/10 transition glow-card"
            >
              <div className="text-lg font-semibold">Company Based Tech Mocs</div>
              <p className="text-sm text-white/70 mt-1">
                Product, Service, and Startup company flows
              </p>
            </button>

            <button
              onClick={() =>
    navigate("/technology-selection", {
      state: {
        company: "Universal Tech Mocks",
        slug: "universal-tech-mocks",
        flow: "universal",
      },
    })
  }
              className="rounded-2xl border border-emerald-400/60 px-6 py-4 text-left backdrop-blur-md bg-white/5 hover:bg-white/10 transition glow-card"
            >
              <div className="text-lg font-semibold">Universal Tech Mocks</div>
              <p className="text-sm text-white/70 mt-1">
                Industry-agnostic rounds used across companies
              </p>
            </button>
          </div>
        </div>
      </main>

      

      {/* Minimal reuse of LaunchPage glow style */}
      <style>{`
        @keyframes glowPulse {
          0% { box-shadow: 0 0 0px 0 rgba(74, 222, 128, 0.30); }
          50% { box-shadow: 0 0 22px 6px rgba(74, 222, 128, 0.75); }
          100% { box-shadow: 0 0 0px 0 rgba(74, 222, 128, 0.30); }
        }
        .glow-card { animation: glowPulse 2.4s ease-in-out infinite; border-color: rgba(74, 222, 128, 0.55); }
      `}</style>
    </div>
  );
}
