// src/components/launch/sections/MockInterviewsSection.jsx
import React from "react";
import { Link } from "react-router-dom";
import { MI_POSITIONS, MI_COMPANIES } from "../../../data/launchData.js";
import Section from "../Section.jsx";

export default function MockInterviewsSection() {
  // Load role GIFs by slug from /assets/position-gifs/*.gif
  const GIF_URLS = React.useMemo(() => {
    const mods = import.meta.glob("../../../assets/position-gifs/*.gif", {
      eager: true,
      as: "url",
    });
    const map = {};
    for (const [path, url] of Object.entries(mods)) {
      const filename = path.split("/").pop() || "";
      const slug = filename.replace(/\.gif$/i, "");
      map[slug] = url;
    }
    return map;
  }, []);

  return (
    <Section>
      <div className="mx-auto max-w-4xl px-3 sm:px-4">
        {/* ===== By Position ===== */}
        <div className="text-center mb-7 md:mb-8">
          <h3 className="text-3xl md:text-4xl font-extrabold tracking-tight">
            <span className="bg-gradient-to-r from-blue-300 via-white to-blue-300 bg-clip-text text-transparent">
              By Position
            </span>
          </h3>
          <p className="mt-2 text-white/75 text-sm md:text-base">
            Pick your target role and start practicing
          </p>
        </div>

        <div className="space-y-8 md:space-y-10 lg:space-y-12">
          {MI_POSITIONS.map((it, idx) => {
            const slug = (it.to?.split("/").pop() || "").trim();
            const gifSrc = GIF_URLS[slug];

            // Alternate placement: 1st left, 2nd right, ...
            const alignClass = idx % 2 ? "ml-auto" : "mr-auto";
            const reverse = idx % 2 !== 0; // when right-aligned, put GIF on the right

            // Text opposite to GIF
            const textAlign = reverse ? "text-left" : "text-right";
            const ctaJustify = reverse ? "justify-start" : "justify-end";

            return (
              <Link
                key={it.to}
                to={it.to}
                className="block"
                aria-label={`Practice ${it.label} interview`}
                title={it.label}
              >
                <div
                  className={[
                    "mi-card",
                    "w-full max-w-[520px] md:max-w-[560px]",
                    alignClass,
                    "flex items-center gap-4 md:gap-5",
                    reverse ? "flex-row-reverse" : "flex-row",
                    "overflow-hidden",
                  ].join(" ")}
                >
                  {/* GIF — no border/box; GIF itself glows + scales on hover */}
                  {gifSrc && (
                    <img
                      src={gifSrc}
                      alt={`${it.label} preview`}
                      loading="lazy"
                      className="mi-gif w-[96px] h-[72px] md:w-[120px] md:h-[88px] object-contain rounded-xl select-none"
                    />
                  )}

                  {/* Text side */}
                  <div className={`min-w-0 ${textAlign}`}>
                    <h4 className="text-base md:text-lg font-semibold truncate">
                      {it.label}
                    </h4>
                    {it.desc && (
                      <p className="mt-1 text-xs md:text-sm text-white/80 leading-relaxed">
                        {it.desc}
                      </p>
                    )}
                    <div className={`mt-2 flex ${ctaJustify}`}>
                      <span className="inline-flex items-center px-2.5 py-1 rounded-full bg-white/10 border border-white/15 transition text-xs">
                        Practice
                      </span>
                    </div>
                  </div>
                </div>
              </Link>
            );
          })}
        </div>

        {/* ===== Company-Specific ===== */}
        <div className="text-center mt-12 md:mt-14 mb-5">
          <h3 className="text-2xl md:text-3xl font-extrabold tracking-tight">
            <span className="bg-gradient-to-r from-emerald-300 via-white to-emerald-300 bg-clip-text text-transparent">
              Company-Specific Mock Interviews
            </span>
          </h3>
          <p className="mt-2 text-white/75 text-sm md:text-base">
            Practice in the style of your target company
          </p>
        </div>

        <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-5">
          {MI_COMPANIES.map((it, i) => {
            const total = MI_COMPANIES.length;
            const isLastTwo = total === 6 && i >= 4;
            return (
              <div key={it.to} className={isLastTwo ? "md:col-span-2" : ""}>
                <Link
                  to={`${it.to.replace(/\/$/, "")}/guide`}
                  className="group block w-full"
                  aria-label={`Practice ${it.label} interview`}
                  title={it.label}
                >
                  <div className="h-12 sm:h-14 md:h-16 flex items-center justify-center">
                    <img
                      src={it.logo}
                      alt={it.label}
                      loading="lazy"
                      className="max-h-full max-w-[160px] w-auto object-contain transition duration-200 opacity-80 group-hover:opacity-100 group-hover:scale-[1.03]"
                    />
                  </div>
                </Link>
              </div>
            );
          })}
        </div>
      </div>

      {/* Local styles */}
      <style>{`
        /* Neutral glass card — no hover glow on the box */
        .mi-card {
          position: relative;
          border-radius: 24px;
          padding: 10px 12px;
          background:
            linear-gradient(180deg, rgba(255,255,255,0.06), rgba(255,255,255,0.02)) padding-box,
            linear-gradient(135deg, rgba(148,163,184,0.30), rgba(148,163,184,0.10)) border-box;
          border: 1px solid transparent;
          backdrop-filter: blur(10px) saturate(115%);
          -webkit-backdrop-filter: blur(10px) saturate(115%);
          box-shadow:
            0 1px 0 rgba(255,255,255,0.05) inset,
            0 6px 14px rgba(0,0,0,0.20);
          transition: background .22s ease;
        }

        /* GIF-only interaction: glow + slight scale-up on hover */
        .mi-gif {
          transition: transform .18s ease, filter .22s ease;
          will-change: transform, filter;
          filter: drop-shadow(0 0 0 rgba(74, 222, 128, 0));
        }
        .mi-gif:hover {
          transform: scale(1.06);
          filter: drop-shadow(0 0 16px rgba(74, 222, 128, 0.40));
        }
      `}</style>
    </Section>
  );
}
