/** --------------------------- Derived Filters --------------------------- */
const ROLES = [
  "All",
  "DSA",
  "Frontend",
  "Backend",
  "Full-Stack",
  "DevOps/Cloud",
  "Data Analyst (SQL)",
  "Data Science/ML",
];

const DIFFICULTIES = ["All", "Easy", "Medium", "Hard"];

const ALL_TOPICS = Array.from(new Set(PROBLEMS.flatMap(p => p.topics))).sort();
const ALL_PATTERNS = Array.from(new Set(PROBLEMS.map(p => p.pattern))).sort();
const ALL_COMPANY = Array.from(new Set(PROBLEMS.flatMap(p => p.companyTags))).sort();

function selectStyle() {
  // White dropdown so text is visible even on dark bg
  return "bg-white text-gray-900 rounded-md px-3 py-2 text-sm shadow focus:outline-none";
}

/** --------------------------- Components --------------------------- */
function StageShortcuts({ onPick }) {
  const items = [
    { k: "nexus", label: "Warm-up for Stage 1: Nexus", preset: { difficulty: "Easy", limit: 15 }},
    { k: "challenge", label: "Stage 2: Challenge (timed)", preset: { difficulty: "Medium", limit: 20 }},
    { k: "perform", label: "Stage 3: Perform (pressure)", preset: { difficulty: "Hard", limit: 25 }},
    { k: "finish", label: "Stage 4–5: Finish (refine)", preset: { difficulty: "Medium", limit: 20 }},
  ];
  return (
    <div className="flex flex-wrap gap-2">
      {items.map(it => (
        <button
          key={it.k}
          onClick={() => onPick(it.preset)}
          className="px-3 py-1.5 rounded-full bg-white/10 border border-white/15 hover:bg-white/15 text-sm"
          title="Apply preset filters"
        >
          {it.label}
        </button>
      ))}
    </div>
  );
}

function Filters({ state, setState }) {
  const on = (k, v) => setState(s => ({ ...s, [k]: v }));

  return (
    <div className="grid md:grid-cols-5 gap-3">
      <select className={selectStyle()} value={state.role} onChange={e => on("role", e.target.value)}>
        {ROLES.map(r => <option key={r} value={r}>{r}</option>)}
      </select>
      <select className={selectStyle()} value={state.difficulty} onChange={e => on("difficulty", e.target.value)}>
        {DIFFICULTIES.map(d => <option key={d} value={d}>{d}</option>)}
      </select>
      <select className={selectStyle()} value={state.topic} onChange={e => on("topic", e.target.value)}>
        <option value="All">All Topics</option>
        {ALL_TOPICS.map(t => <option key={t} value={t}>{t}</option>)}
      </select>
      <select className={selectStyle()} value={state.pattern} onChange={e => on("pattern", e.target.value)}>
        <option value="All">All Patterns</option>
        {ALL_PATTERNS.map(p => <option key={p} value={p}>{p}</option>)}
      </select>
      <select className={selectStyle()} value={state.company} onChange={e => on("company", e.target.value)}>
        <option value="All">All Companies/Styles</option>
        {ALL_COMPANY.map(c => <option key={c} value={c}>{c}</option>)}
      </select>
    </div>
  );
}

function ProblemCard({ p, onOpen }) {
  return (
    <button
      onClick={onOpen}
      className="group text-left rounded-2xl border border-white/10 bg-white/[0.04] hover:bg-white/[0.07] transition p-4"
    >
      <div className="flex items-center justify-between gap-3">
        <h3 className="font-semibold">{p.title}</h3>
        <span className={cx(
          "text-xs px-2 py-1 rounded-full",
          p.difficulty === "Easy" && "bg-emerald-400 text-gray-900",
          p.difficulty === "Medium" && "bg-amber-300 text-gray-900",
          p.difficulty === "Hard" && "bg-rose-300 text-gray-900",
        )}>{p.difficulty}</span>
      </div>
      <p className="text-white/75 text-sm mt-1">{p.statement}</p>
      <div className="mt-2 flex flex-wrap gap-1">
        {p.topics.slice(0,3).map(t => (
          <span key={t} className="text-[11px] px-2 py-0.5 rounded-full bg-white/10 border border-white/15">{t}</span>
        ))}
        <span className="text-[11px] px-2 py-0.5 rounded-full bg-white/10 border border-white/15">{p.pattern}</span>
        {p.companyTags.slice(0,2).map(c => (
          <span key={c} className="text-[11px] px-2 py-0.5 rounded-full bg-white/10 border border-white/15">{c}</span>
        ))}
      </div>
      <div className="mt-3 text-xs text-white/60 flex items-center gap-3">
        <span>Time: {p.timeLimit}m</span>
        <span>Est: {p.estSolveMins}m</span>
        <span>Success: {p.successRate}%</span>
      </div>
    </button>
  );
}

function ProblemModal({ p, mode, onClose, onStartTimer }) {
  const [showHints, setShowHints] = useState(mode !== "Interview");
  const [showSolution, setShowSolution] = useState(mode === "Learn");
  const [secondsLeft, setSecondsLeft] = useState(0);

  useEffect(() => {
    let id;
    if (secondsLeft > 0) {
      id = setInterval(()=> setSecondsLeft(s => s - 1), 1000);
    }
    return () => id && clearInterval(id);
  }, [secondsLeft]);

  const startTimer = () => {
    setSecondsLeft(p.timeLimit * 60);
    onStartTimer?.();
  };

  const mm = Math.floor(secondsLeft / 60);
  const ss = secondsLeft % 60;

  useEffect(() => {
    // remember last opened problem
    save("coding.lastProblemId", p.id);
  }, [p.id]);

  return (
    <div className="fixed inset-0 z-50">
      <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={onClose} />
      <div className="relative z-10 max-w-3xl mx-auto my-10 rounded-2xl border border-white/10 bg-[#0b1224] p-5">
        <div className="flex items-start justify-between gap-3">
          <h3 className="text-xl font-bold">{p.title}</h3>
          <button onClick={onClose} className="px-2 py-1 rounded bg-white/10 hover:bg-white/15">✕</button>
        </div>

        <p className="mt-2 text-white/80">{p.statement}</p>

        {p.examples?.length > 0 && (
          <div className="mt-3 rounded-lg bg-white/5 border border-white/10 p-3 text-sm">
            <p className="font-semibold mb-1">Example</p>
            {p.examples.map((ex, i) => (
              <pre key={i} className="text-white/80 whitespace-pre-wrap">{`Input: ${ex.input}\nOutput: ${ex.output}`}</pre>
            ))}
          </div>
        )}

        {/* Tags */}
        <div className="mt-3 flex flex-wrap gap-1 text-xs">
          {[...p.topics, p.pattern, ...p.companyTags].map(t => (
            <span key={t} className="px-2 py-0.5 rounded-full bg-white/10 border border-white/15">{t}</span>
          ))}
        </div>

        {/* Mode controls */}
        <div className="mt-4 flex flex-wrap items-center gap-2">
          <span className="text-xs text-white/70">Mode:</span>
          {["Learn","Practice","Interview"].map(m => (
            <span
              key={m}
              className={cx(
                "text-xs px-3 py-1 rounded-full border cursor-default",
                m===mode ? "bg-gradient-to-r from-blue-400 via-blue-300 to-blue-400 text-gray-900 border-transparent" : "bg-white/10 border-white/15"
              )}
            >
              {m}
            </span>
          ))}
          {mode === "Interview" && (
            <button
              onClick={startTimer}
              className="ml-auto px-3 py-1.5 rounded-full bg-white/10 border border-white/15 hover:bg-white/15 text-sm"
            >
              {secondsLeft>0 ? `⏱ ${mm}:${ss.toString().padStart(2,'0')}` : `Start ${p.timeLimit}m timer`}
            </button>
          )}
        </div>

        {/* Hints/Solution */}
        <div className="mt-4 space-y-3">
          <div className="rounded-lg border border-white/10">
            <button
              onClick={()=>setShowHints(s=>!s)}
              className="w-full text-left px-3 py-2 font-semibold bg-white/5 hover:bg-white/10 rounded-t-lg"
            >
              Hints
            </button>
            {showHints && (
              <ul className="px-4 py-3 list-disc pl-5 text-sm text-white/80">
                {p.hints.map((h,i)=><li key={i}>{h}</li>)}
              </ul>
            )}
          </div>
          <div className="rounded-lg border border-white/10">
            <button
              onClick={()=>setShowSolution(s=>!s)}
              className="w-full text-left px-3 py-2 font-semibold bg-white/5 hover:bg-white/10 rounded-t-lg"
            >
              Solution
            </button>
            {showSolution && (
              <div className="px-4 py-3 text-sm text-white/80 whitespace-pre-wrap">
                {p.solution}
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

/** --------------------------- Page --------------------------- */
export default function CodingProblems() {
  const qs = useQS();
  const navigate = useNavigate();

  // initial filter state (from query params if provided by packs/guide)
  const [filters, setFilters] = useState({
    role: qs.get("role") || "All",
    difficulty: qs.get("difficulty") || "All",
    topic: qs.get("topic") || "All",
    pattern: qs.get("pattern") || "All",
    company: qs.get("company") || "All",
  });

  const [mode, setMode] = useState(qs.get("mode") || "Practice"); // Learn | Practice | Interview
  const [open, setOpen] = useState(null);

  // Continue where you left off
  const lastId = load("coding.lastProblemId");
  const lastProblem = PROBLEMS.find(p => p.id === lastId) || null;

  // derived list
  const list = useMemo(() => {
    return PROBLEMS.filter(p => {
      if (filters.role !== "All" && p.role !== filters.role) return false;
      if (filters.difficulty !== "All" && p.difficulty !== filters.difficulty) return false;
      if (filters.topic !== "All" && !p.topics.includes(filters.topic)) return false;
      if (filters.pattern !== "All" && p.pattern !== filters.pattern) return false;
      if (filters.company !== "All" && !p.companyTags.includes(filters.company)) return false;
      return true;
    });
  }, [filters]);

  // write filters to URL for deep-linking
  useEffect(() => {
    const params = new URLSearchParams();
    Object.entries(filters).forEach(([k,v]) => v!=="All" && params.set(k,v));
    if (mode !== "Practice") params.set("mode", mode);
    navigate({ search: params.toString() }, { replace: true });
  }, [filters, mode]);

  const applyStagePreset = (preset) => {
    setFilters(s => ({ ...s, difficulty: preset.difficulty || s.difficulty }));
    // optional: store timer preference using preset.limit
  };

  return (
    <div className="min-h-screen bg-[#0f172a] text-white">
      <div className="mx-auto max-w-7xl px-4 pt-10 pb-16">
        {/* Command Center */}
        <header className="rounded-2xl border border-white/10 bg-white/[0.04] backdrop-blur p-6 md:p-8 relative overflow-hidden">
          <div
            aria-hidden
            className="absolute -top-24 -right-24 h-72 w-72 rounded-full blur-3xl opacity-30"
            style={{ background: `radial-gradient(closest-side, rgba(147,197,253,.6), rgba(147,197,253,0))` }}
          />
          <h1 className="text-3xl md:text-5xl font-extrabold tracking-tight">
            <span className="bg-gradient-to-r from-blue-300 via-white to-blue-300 bg-clip-text text-transparent">
              Coding Problems
            </span>
          </h1>
          <p className="mt-3 text-white/80 max-w-3xl">
            Practice that mirrors real interviews. Learn patterns, communicate clearly, and level up for each stage of our mock interview journey.
          </p>

          <div className="mt-5 flex flex-wrap items-center gap-3">
            <div className="rounded-xl border border-white/10 bg-white/5 px-4 py-3">
              <div className="text-xs text-white/70">Mode</div>
              <div className="mt-1 flex gap-2">
                {["Learn","Practice","Interview"].map(m => (
                  <button
                    key={m}
                    onClick={()=>setMode(m)}
                    className={cx(
                      "px-3 py-1.5 rounded-full text-sm font-semibold transition",
                      mode === m
                        ? "bg-gradient-to-r from-blue-400 via-blue-300 to-blue-400 text-gray-900"
                        : "bg-white/10 hover:bg-white/20"
                    )}
                  >
                    {m}
                  </button>
                ))}
              </div>
            </div>

            <div className="rounded-xl border border-white/10 bg-white/5 px-4 py-3">
              <div className="text-xs text-white/70 mb-1">Stage shortcuts</div>
              <StageShortcuts onPick={applyStagePreset} />
            </div>

            {lastProblem && (
              <button
                onClick={()=>setOpen(lastProblem)}
                className="ml-auto px-3 py-2 rounded-full bg-white/10 border border-white/15 hover:bg-white/15 text-sm"
              >
                Continue: {lastProblem.title}
              </button>
            )}
          </div>
        </header>

        {/* Filters */}
        <div className="mt-6 rounded-2xl border border-white/10 bg-white/[0.04] p-4">
          <Filters state={filters} setState={setFilters} />
        </div>

        {/* Grid */}
        <section className="mt-6 grid sm:grid-cols-2 lg:grid-cols-3 gap-4">
          {list.map(p => (
            <ProblemCard key={p.id} p={p} onOpen={() => setOpen(p)} />
          ))}
          {list.length === 0 && (
            <div className="col-span-full rounded-xl border border-white/10 bg-white/5 p-6 text-center text-white/80">
              No problems match the current filters. Try broadening your selection.
            </div>
          )}
        </section>
      </div>

      {open && (
        <ProblemModal
          p={open}
          mode={mode}
          onClose={()=>setOpen(null)}
          onStartTimer={()=>{}}
        />
      )}
    </div>
  );
}
